import numpy as np

class HeterogeneousBasin:
    def __init__(self, dim=5):
        self.dim = dim
        # Define different scales for each dimension to create heterogeneity
        self.scales = np.array([1.0, 0.5, 2.0, 0.25, 1.5])[:dim]
        # Define different types of functions for each dimension
        self.function_types = np.array(['quadratic', 'sinusoidal', 'absolute', 'quadratic', 'sinusoidal'])[:dim]

    def f(self, x):
        total = 0.0
        for i in range(self.dim):
            xi = x[i]
            scale = self.scales[i]
            func_type = self.function_types[i]

            if func_type == 'quadratic':
                term = (xi / scale) ** 2
            elif func_type == 'sinusoidal':
                term = np.sin(5 * xi / scale) ** 2 - 0.5
            elif func_type == 'absolute':
                term = np.abs(xi / scale) ** 0.5
            else:
                term = 0.0

            total += term

        return total

