class HeterogeneousBasin:
    def __init__(self, dim=5):
        self.dim = dim
        # Define different basin structures for each dimension
        self.basin_types = ['quadratic', 'absolute', 'sinusoidal', 'cubic', 'exponential']
        self.basin_types = self.basin_types[:dim]  # Ensure we don't exceed the dimension

    def f(self, x):
        total = 0.0
        for i in range(self.dim):
            xi = x[i]
            if self.basin_types[i] == 'quadratic':
                # Sharp quadratic basin
                total += 100 * (xi**2)
            elif self.basin_types[i] == 'absolute':
                # Flat basin with sharp edges
                total += np.abs(xi)
            elif self.basin_types[i] == 'sinusoidal':
                # Multiple local minima
                total += 1 + 0.1 * (xi**2) + 5 * np.sin(5 * xi)
            elif self.basin_types[i] == 'cubic':
                # Asymmetric basin
                total += (xi**3) + 0.1 * (xi**2)
            elif self.basin_types[i] == 'exponential':
                # Very sharp basin near zero
                total += np.exp(5 * np.abs(xi)) - 1
        return total

